{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g).map(Number); return m;};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bgOf=el=>{let e=el; while(e){const c=getComputedStyle(e).backgroundColor; const p=parse(c); if(p.length<4||p[3]>0) return p.slice(0,3); e=e.parentElement||(e.getRootNode().host);} return [255,255,255]};
const cr=(a,b)=>{const l1=lum(a),l2=lum(b); return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)};
const out=[];
const badges=[...document.querySelectorAll('tbody td')].filter((td,i)=>td.cellIndex===7).map(td=>{let e=td; while(e.firstElementChild) e=e.firstElementChild; return e;});
for(const e of badges){const cs=getComputedStyle(e); out.push({t:e.textContent.trim(), cls:e.className+' | '+e.parentElement.className+' | '+e.parentElement.parentElement.className, fg:cs.color, bg:bgOf(e).join(','), fs:cs.fontSize, fw:cs.fontWeight, cr:cr(parse(cs.color),bgOf(e))});}
// placeholder
const inp=document.querySelector('br-input').shadowRoot.querySelector('input'); const ps=getComputedStyle(inp,'::placeholder'); out.push({t:'placeholder', fg:ps.color, fs:ps.fontSize, style:ps.fontStyle, bg:bgOf(inp).join(','), cr:cr(parse(ps.color),bgOf(inp))});
// other texts
const sel=['thead th','tbody td','a[role=button]'];
for(const s of sel){const e=document.querySelector(s); const cs=getComputedStyle(e); out.push({t:s, fg:cs.color, bg:bgOf(e).join(','), fs:cs.fontSize, cr:cr(parse(cs.color),bgOf(e))});}
const ua=[...document.querySelectorAll('div,span')].find(e=>/^Última atualização/.test(e.textContent.trim())&&e.children.length<3); if(ua){const cs=getComputedStyle(ua); out.push({t:'ultima '+ua.className, fg:cs.color, fs:cs.fontSize, bg:bgOf(ua).join(','), cr:cr(parse(cs.color),bgOf(ua))});}
const chip=document.querySelectorAll('span.br-tag')[1]; const inner=[...chip.querySelectorAll('*')].map(x=>{const cs=getComputedStyle(x); return x.tagName+'.'+x.className+' '+cs.color+' '+cs.fontSize+' cr='+cr(parse(cs.color),bgOf(x))}); out.push({chip:inner, chipColor:getComputedStyle(chip).color});
const lim=document.querySelector('br-button[label="Limpar filtros"]'); out.push({lim:lim.shadowRoot.querySelector('button').outerHTML.slice(0,200)});
return out;}"}

